mapper.select:
select  from merchant_crm_export_task
where merchant_id = #{merchantId} and request_id = #{requestId}
limit 1

select  from merchant_crm_export_task t
where t.merchant_id = #{merchantId}
  and t.merchant_owner_member_id = #{ownerMemberId}
  and t.id = #{taskId}
  and exists (
    select 1 from mms_merchant m
    where m.id = t.merchant_id and m.member_id = t.merchant_owner_member_id
      and m.status = 1 and m.account_status = 1 and m.del_flag = 0
  )
limit 1

select  from merchant_crm_export_task
where merchant_id = #{merchantId} and id = #{taskId}
limit 1
